package com.campus.registration.repository; import com.campus.registration.model.*;import java.sql.*;import java.util.*; public class CourseRepository{final Database db;public CourseRepository(Database d){db=d;}public void save(Course x)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("INSERT OR REPLACE INTO courses VALUES(?,?,?,?)")){p.setString(1,x.code());p.setString(2,x.name());p.setInt(3,x.credits());p.setInt(4,x.capacity());p.executeUpdate();for(String pr:x.prerequisites())try(var q=c.prepareStatement("INSERT OR IGNORE INTO prerequisites VALUES(?,?)")){q.setString(1,x.code());q.setString(2,pr);q.executeUpdate();}}}public void saveSection(Section x)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("INSERT OR REPLACE INTO sections VALUES(?,?,?,?,?,?)")){p.setString(1,x.courseCode());p.setString(2,x.section());p.setString(3,x.day());p.setInt(4,x.start());p.setInt(5,x.end());p.setString(6,x.room());p.executeUpdate();}}public Course get(String code)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("SELECT * FROM courses WHERE code=?")){p.setString(1,code);try(var r=p.executeQuery()){if(!r.next())return null;List<String>a=new ArrayList<>();try(var q=c.prepareStatement("SELECT prereq FROM prerequisites WHERE course=?")){q.setString(1,code);try(var z=q.executeQuery()){while(z.next())a.add(z.getString(1));}}return new Course(r.getString(1),r.getString(2),r.getInt(3),r.getInt(4),a);}}}public List<Course> all()throws SQLException{List<Course>a=new ArrayList<>();try(var c=db.connect();var s=c.createStatement();var r=s.executeQuery("SELECT code FROM courses ORDER BY code")){while(r.next())a.add(get(r.getString(1)));}return a;}public Section section(String code,String sec)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("SELECT * FROM sections WHERE course=? AND section=?")){p.setString(1,code);p.setString(2,sec);try(var r=p.executeQuery()){return r.next()?new Section(r.getString(1),r.getString(2),r.getString(3),r.getInt(4),r.getInt(5),r.getString(6)):null;}}}}